-- Seed: catálogo inicial de sneakpeekmiami.com (732 productos)
-- Generado scrapeando https://sneakpeekmiami.com/products.json
-- Idempotente: ON CONFLICT (slug) DO NOTHING al final.

-- 732 products from sneakpeekmiami.com (full catalog)
ON CONFLICT (slug) DO NOTHING;

-- Promover metadata Shopify a columnas dedicadas (no perder nada del scrape).
update public.upsoled_products
set
    shopify_id = nullif(metadata->>'shopify_id', '')::bigint,
    shopify_handle = nullif(metadata->>'shopify_handle', ''),
    product_type = nullif(metadata->>'shopify_product_type', ''),
    shopify_tags_raw = nullif(metadata->>'shopify_tags_raw', ''),
    source = coalesce(nullif(source, ''), 'sneakpeekmiami'),
    tags = case
        when coalesce(array_length(tags, 1), 0) = 0
             and nullif(metadata->>'shopify_tags_raw', '') is not null
        then (
            select coalesce(array_agg(trim(t)), '{}'::text[])
            from unnest(string_to_array(metadata->>'shopify_tags_raw', ',')) as t
            where trim(t) <> ''
        )
        else tags
    end
where metadata ? 'shopify_id';
